/* ---------- Ticket list ---------- */
/* support tickets the agent has triaged. Its content sits 16px in from every edge in every style: the title and the switch in
   the head, then the tickets, each a row whose hover fill reaches out 8px round its dot and words with the card's rounding
   (never a sharp band across the card). An open ticket shows the question and the suggested reply on the title's column,
   with no band behind it; the reply is a field you can edit, and Send and solve ends on the content's right edge. The card
   grows and shrinks with what it shows (grow()), so it keeps no room for a ticket to open */
.tkx{padding:var(--dm-s-4) var(--dm-s-4) var(--dm-s-2);display:flex;flex-direction:column;gap:var(--dm-s-2)}
.tkx-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);min-height:28px;font-size:14px}
.tkx-h b{font-weight:500}
.tkx-sg button{font-size:12px;height:24px;padding:0 10px}
.tkx-list{display:flex;flex-direction:column;gap:2px;margin:0 calc(-1 * var(--dm-s-2))}
.tkx :is(.pill,.ib):active{transform:none}
.tkx-r{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:10px;width:100%;padding:var(--dm-s-2);border-radius:calc(var(--dm-r-card) - 8px);text-align:left;transition:background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.tkx-r:hover{background:color-mix(in srgb,var(--dm-fg) 4%,transparent)}}
.tkx-r .pr{display:flex;align-items:center;justify-content:center;width:18px;height:18px}
.tkx-r .pr .dot{width:8px;height:8px}
.tkx-r .t{display:flex;flex-direction:column;min-width:0;font-size:13px}
.tkx-r .t b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tkx-r .t span{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tkx-r .m{display:flex;align-items:center;gap:6px}
.tkx-r .m .av{width:20px;height:20px;font-size:9px}
.tkx-r .w{font-size:11.5px;color:var(--dm-muted)}
/* a ticket's priority is a vivid mark, 3:1 on the surface: urgent red, high orange, normal the accent's mark, low a grey that
   holds 3:1 too */
.tkx-r .dot[data-p="urgent"]{color:var(--dm-bad-mark)}.tkx-r .dot[data-p="high"]{color:var(--dm-warn-mark)}.tkx-r .dot[data-p="normal"]{color:var(--dm-accent-mark,var(--dm-accent))}.tkx-r .dot[data-p="low"]{color:color-mix(in srgb,var(--dm-muted) 80%,var(--dm-surface))}
.tkx-d{padding:4px var(--dm-s-2) var(--dm-s-3) 36px;display:flex;flex-direction:column;gap:var(--dm-s-3)}
.tkx-q{font-size:12.5px;line-height:1.5;color:var(--dm-fg2)}
/* the suggested reply is a field: a quiet grey edge at rest, one step stronger while you edit it, and nothing else changes */
.tkx-s{padding:10px var(--dm-s-3) var(--dm-s-3);border-radius:var(--dm-r-box);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font-size:12.5px;line-height:1.5;color:var(--dm-fg);transition:box-shadow var(--dm-t-fast)}
.tkx-s:focus-within{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
@supports (corner-shape:squircle){.tkx-s{corner-shape:squircle;border-radius:var(--dm-r-box-sq)}}
.tkx-s .lb{display:flex;align-items:center;gap:6px;font-size:11.5px;color:var(--dm-accent-fg,var(--dm-accent));font-weight:500;margin-bottom:var(--dm-s-1)}
/* the reply reads as text you can edit: the text cursor over it, and an accent caret once it has focus */
.tkx-s [contenteditable]{outline:0;cursor:text;caret-color:var(--dm-accent-fg,var(--dm-accent))}
.tkx-a{display:flex;gap:var(--dm-s-2);justify-content:flex-end}
/* nothing left in a view: the empty state, a small sketch of a list on a card, a title and one muted line */
.tkx-em{display:flex;flex-direction:column;align-items:center;gap:4px;padding:var(--dm-s-4) var(--dm-s-2) var(--dm-s-5);text-align:center}
.tkx-em b{font-size:13.5px;line-height:18px;font-weight:500;color:var(--dm-fg)}
.tkx-em>span:not(.tkx-em-art){max-width:290px;font-size:12.5px;line-height:1.5;color:var(--dm-muted)}
.tkx-em-art{position:relative;display:block;width:136px;height:70px;margin:0 0 12px;border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.tkx-em-art::before{content:"";position:absolute;left:14px;top:16px;width:8px;height:8px;border-radius:50%;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,color-mix(in srgb,var(--dm-chip) 55%,var(--dm-surface)))}
.tkx-em-art::after{content:"";position:absolute;left:32px;top:17px;width:58px;height:6px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,color-mix(in srgb,var(--dm-chip) 55%,var(--dm-surface)))}
:root:not([data-style="soft"],[data-style="clean"]) .tkx-em-art:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:0 0 0 1px var(--dm-line)}
.tkx-t.leave{animation:leave .35s var(--dm-ease) both}
/* Clean: the head is an off-white strip with the switch 16px from the card's top and right edges and the
   strip's hairline (owner, 23 Nov) and the title 16px in; the reply's label is grey like the rest of the chrome, and Edit is the flat
   secondary beside the ink Send and solve */
:root[data-style="clean"] .tkx,:root [data-style="clean"] .tkx,:root [data-style="clean"].tkx{padding-top:0}
:root[data-style="clean"] .tkx-h,:root [data-style="clean"] .tkx-h,:root [data-style="clean"].tkx-h{margin:0 -16px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0;line-height:28px}
:root[data-style="clean"] .tkx-s .lb,:root [data-style="clean"] .tkx-s .lb,:root [data-style="clean"].tkx-s .lb{color:var(--dm-fg2)}
:root[data-style="clean"] .tkx-a .pill.ghost,:root [data-style="clean"] .tkx-a .pill.ghost,:root [data-style="clean"].tkx-a .pill.ghost{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .tkx-a .pill.ghost:hover,:root [data-style="clean"] .tkx-a .pill.ghost:hover,:root [data-style="clean"].tkx-a .pill.ghost:hover{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .tkx-a .pill.ghost:active,:root [data-style="clean"] .tkx-a .pill.ghost:active,:root [data-style="clean"].tkx-a .pill.ghost:active{box-shadow:var(--dm-btn2-press)}

DM.def('ticket-list', (r, c) => {
  // Clean's one hover: a highlight that glides from row to row (hoverGlide)
  // (an open ticket's row has no fill of its own, so every row takes the glide alone)
  c.offs.push(hoverGlide($('.tkx', r), '.tkx-r', { keep:':not(*)' }));
  const T = [
    { p:'urgent', pn:'Urgent', t:'Agent stopped mid export', f:'Northwind', a:['MK','var(--dm-av-l)'], w:'4m', q:'The token export stopped at 60% and nothing has happened for 20 minutes.', s:'Sorry about that. The run paused at your $5 spend cap. I have raised it for this run and it finished just now. Your tokens are in the Exports tab.', st:'open' },
    { p:'high', pn:'High', t:'Figma frames not syncing', f:'Lumen Labs', a:['JO','var(--dm-av-m)'], w:'22m', q:'New frames from this morning are not showing up in DesignMe.', s:'The Figma token for your workspace expired yesterday. Reconnect it from Settings, then the frames will sync within a minute.', st:'open' },
    { p:'normal', pn:'Normal', t:'How do I share a run?', f:'Orbit', a:['DA','var(--dm-av-b)'], w:'1h', q:'Can I send an agent run to someone outside my team?', s:'Yes. Open the run, click Share, and turn on "Anyone with the link". They can view it without an account.', st:'open' },
    { p:'low', pn:'Low', t:'Invoice address change', f:'Kite Health', a:['MK','var(--dm-av-l)'], w:'2d', q:'', s:'', st:'done' }
  ];
  const list = $('.tkx-list', r); let f = 'open', open = null;
  function paint(anim){
    const L = T.filter(t => t.st === f);
    list.innerHTML = L.length ? L.map(t => `<div class="tkx-t${open === t ? ' open' : ''}"><button class="tkx-r" aria-expanded="${open === t}"><span class="pr" data-tip="${t.pn}"><span class="dot" data-p="${t.p}"></span></span><span class="t"><b>${t.t}</b><span>${t.f}${t.q && open !== t ? ' · ' + t.q : ''}</span></span><span class="m"><span class="w">${t.w}</span>${AV(t.a[0], t.a[1])}</span></button>${open === t ? `<div class="tkx-d"><div class="tkx-q">${t.q}</div><div class="tkx-s"><div class="lb">${I('spark','xs')}Suggested reply</div><div class="tx" contenteditable="true" spellcheck="false">${t.s}</div></div><div class="tkx-a"><button class="pill ghost sm ed">${I('edit','xs')}Edit</button><button class="pill accent sm sd">${I('send','xs')}Send and solve</button></div></div>` : ''}</div>`).join('') : `<div class="tkx-em"><span class="tkx-em-art" aria-hidden="true"></span><b>${f === 'open' ? 'All caught up' : 'Nothing solved yet'}</b><span>${f === 'open' ? 'New tickets show up here' : 'Solved tickets show up here'}</span></div>`;
    if (anim) stagger($$('.tkx-t', list), 40);
    $$('.tkx-t', list).forEach((el, i) => { const t = L[i];
      $('.tkx-r', el).onclick = () => { open = open === t ? null : t; paint(); const d = $('.tkx-d', list); if (d) stagger([...d.children], 50); };
      // a solved ticket fades, then folds its height away, so the tickets under it slide up instead of jumping
      // while it sends, a spinner takes the icon's place and the words stay, so the button keeps its width and never goes blank
      const sd = $('.sd', el); if (sd) sd.onclick = () => c.run(async () => { if (sd.getAttribute('aria-busy') === 'true') return; sd.setAttribute('aria-busy', 'true'); $('.i', sd).replaceWith(html('<span class="spin"></span>')); await c.wait(700); t.s = $('.tx', el).textContent; t.st = 'done'; open = null; el.classList.add('leave'); await c.wait(330);
        if (!REDUCE){ el.style.overflow = 'hidden'; await el.animate([{ height:el.offsetHeight + 'px' }, { height:'0px' }], { duration:260, easing:'cubic-bezier(.22,1,.36,1)', fill:'forwards' }).finished.catch(() => {}); }
        if (!c.dead) paint(); });
      const ed = $('.ed', el); if (ed) ed.onclick = () => { const tx = $('.tx', el); tx.focus({ preventScroll:true }); const s = document.getSelection(); s.selectAllChildren(tx); s.collapseToEnd(); };
    });
  }
  seg($('.tkx-sg', r), v => { f = v; open = null; paint(true); });
  paint(true);
  // as tickets open, close, leave or change with the filter, the card eases to its new height (grow()) and stays centred in its
  // stage, keeping no room for a ticket to open
  c.offs.push(grow($('.tkx', r)));
  // the preview opens the first ticket on its own, unless you take over first
  c.auto(1000, () => { if (!open){ open = T[0]; paint(); stagger([...$('.tkx-d', list).children], 50); } });
});
